const fs = require("fs");
const path = require("path");

function serializeSnowModule(payload) {
  const meta = JSON.stringify(
    {
      generatedAt: payload.generatedAt,
      provider: payload.provider,
      historicalMethod: payload.historicalMethod,
      historyWindow: payload.historyWindow
    },
    null,
    2
  );

  const snapshot = JSON.stringify(payload.resorts, null, 2);

  return [
    "// This file is generated by scripts/update-snow-data.cjs or scripts/generate-snow-data.cjs",
    "// It is safe to commit because the app is static-hosted.",
    "",
    `export const snowSnapshotMeta = ${meta};`,
    "",
    `export const snowSnapshot = ${snapshot};`,
    ""
  ].join("\n");
}

function writeSnowModule(payload) {
  const outputPath = path.resolve(__dirname, "..", "..", "js", "snow-data.js");
  fs.writeFileSync(outputPath, serializeSnowModule(payload), "utf8");
}

module.exports = { serializeSnowModule, writeSnowModule };
